from airline_helper import get_tools
import json

db, tools = get_tools()

# Gather all routes from SFO with available dates and pricing
sfo_routes = {}
for fid, f in db.flights.items():
    if f.origin == 'SFO':
        for d, status in f.dates.items():
            if status.status == 'available':
                key = (f.destination, d)
                if key not in sfo_routes:
                    sfo_routes[key] = []
                info = {
                    'flight_number': fid,
                    'origin': f.origin,
                    'destination': f.destination,
                    'date': d,
                    'departure': f.scheduled_departure_time_est,
                    'arrival': f.scheduled_arrival_time_est,
                    'prices': status.prices if hasattr(status, 'prices') else {},
                    'available_seats': status.available_seats if hasattr(status, 'available_seats') else {},
                }
                sfo_routes[key].append(info)

# Get all one-stop options from SFO on available dates (to any reachable destination)
all_destinations = set(f.destination for f in db.flights.values())
all_dates = sorted(set(d for f in db.flights.values() for d in f.dates.keys()))

onestop_results = {}
for dest in sorted(all_destinations):
    if dest == 'SFO':
        continue
    for date in all_dates:
        result = tools.search_onestop_flight('SFO', dest, date)
        if isinstance(result, list) and len(result) > 0:
            key = f"SFO->{dest} on {date}"
            onestop_results[key] = []
            for pair in result:
                if isinstance(pair, list):
                    flight_pair = []
                    for fl in pair:
                        d = fl.model_dump() if hasattr(fl, 'model_dump') else fl
                        flight_pair.append(d)
                    onestop_results[key].append(flight_pair)

output = {
